using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad] public static class FixedArrowVerification {
  static double start;static readonly List<string> checks=new List<string>();
  static FixedArrowVerification(){if(SessionState.GetBool("FixedArrowVerify",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
  public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/TacticalSandbox.unity");SessionState.SetBool("FixedArrowVerify",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.EnterPlaymode();}
  static void Check(bool value,string message){if(!value)throw new Exception(message);checks.Add("PASS "+message);}
  static bool Route(BattleUnit u,Vector2 end){var p=u.transform.position;return u.Motor.Commit(new[]{new RoadPoint(p.x,p.y),new RoadPoint(end.x,end.y)},()=>1);}
  static Vector3[] Points(MergedMovementArrows arrows){return arrows.GetComponentsInChildren<LineRenderer>().Where(l=>l.name=="空心合并箭头轮廓"&&l.enabled).SelectMany(l=>{var p=new Vector3[l.positionCount];l.GetPositions(p);return p;}).ToArray();}
  static void Poll(){try{if(EditorApplication.timeSinceStartup-start>90)throw new Exception("verification timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;
   foreach(var ai in UnityEngine.Object.FindObjectsOfType<MonoBehaviour>())if(ai.GetType().Name.StartsWith("AI"))ai.enabled=false;foreach(var u in w.units)u.Motor.Stop();var friendly=w.units.Where(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry).ToArray();var a=friendly[0];var b=friendly[1];foreach(var u in friendly){var march=u.GetComponent<LocalMarchOrder>();if(march==null)march=u.gameObject.AddComponent<LocalMarchOrder>();march.world=w;march.style=LocalMarchStyle.Forced;u.UnderFire=false;u.SetWorking(false);}
   var visual=w.GetComponent<MergedMovementArrows>();a.transform.position=new Vector3(-7,0);b.transform.position=new Vector3(-12,-5);Check(Route(a,new Vector2(-3,0)),"accept initial movement order");visual.Refresh();var initialStart=a.Motor.ArrowOrderStart;var initialEnd=a.Motor.ArrowOrderEnd;var initialDirection=a.Motor.ArrowOrderDirection;uint revision=a.Motor.ArrowOrderRevision;int builds=visual.GeometryBuildCount;var before=Points(visual);
   a.Motor.Tick(.5f);visual.Refresh();Check(Vector2.Distance(a.transform.position,initialStart)>.3f,"unit actually moves during verification");Check(visual.Inputs[0].start==initialStart&&visual.Inputs[0].route.Last()==initialEnd,"visual start and destination remain at accepted order anchors");Check(visual.Inputs[0].direction==initialDirection,"visual initial direction remains fixed");Check((visual.Inputs[0].detectionPosition??visual.Inputs[0].start)==initialStart,"detector stays anchored to visible arrow origin");Check(visual.GeometryBuildCount==builds,"movement without group change does not rebuild geometry");Check(before.SequenceEqual(Points(visual)),"every displayed contour point remains unchanged while unit moves");
   var current=(Vector2)a.transform.position;Check(Route(a,initialEnd),"accept a new order with same destination");Check(a.Motor.ArrowOrderRevision!=revision&&a.Motor.ArrowOrderStart==current,"new command captures new initial position even when destination matches");visual.Refresh();Check(visual.GeometryBuildCount>builds&&!before.SequenceEqual(Points(visual)),"new command replaces the cached arrow");var saved=a.Motor.ArrowOrderStart;revision=a.Motor.ArrowOrderRevision;Check(!a.Motor.Commit(new[]{new RoadPoint(100,100),new RoadPoint(101,100)},()=>1)&&a.Motor.ArrowOrderRevision==revision&&a.Motor.ArrowOrderStart==saved,"rejected command preserves existing arrow anchors");
   b.transform.position=a.transform.position+Vector3.up;Check(Route(b,new Vector2(-2,2)),"second movement order accepted later");visual.Refresh();Check(visual.MergedGroupCount==1,"later movement can merge with an existing order");before=Points(visual);builds=visual.GeometryBuildCount;a.Motor.Tick(.2f);b.Motor.Tick(.2f);visual.Refresh();Check(visual.MergedGroupCount==1&&visual.GeometryBuildCount==builds&&before.SequenceEqual(Points(visual)),"merged outline stays fixed while same members move");
   b.transform.position=new Vector3(-6,5);visual.Refresh();Check(visual.MergedGroupCount==1&&before.SequenceEqual(Points(visual)),"moving a unit away does not change detection of its persistent fixed arrow");Route(b,new Vector2(-2,5));visual.Refresh();Check(visual.GroupCount==2&&visual.MergedGroupCount==0,"a new distant arrow causes groups to be recomputed");Check(visual.Inputs.First(i=>i.id==b.unitId).start==b.Motor.ArrowOrderStart,"new arrow uses its own new origin");b.transform.position=a.transform.position+Vector3.up;Route(b,new Vector2(-2,2));visual.Refresh();Check(visual.MergedGroupCount==1,"new nearby arrow is detected even when issued at a different time");
   var first=new MovementArrowGeometry.Input{id="p",owner="A",start=Vector2.zero,direction=Vector2.right,radius=.5f,route=new List<Vector2>{Vector2.zero,new Vector2(8,0)}};var passing=new MovementArrowGeometry.Input{id="q",owner="A",start=new Vector2(-5,0),direction=Vector2.right,radius=.5f,route=new List<Vector2>{new Vector2(-5,0),new Vector2(5,0)}};Check(MovementArrowGeometry.Groups(new[]{first,passing}).Count==1,"another arrow entering an origin radius is detected even if the two origins are far apart");passing.start=new Vector2(4,-5);passing.direction=Vector2.up;passing.route=new List<Vector2>{passing.start,new Vector2(4,5)};Check(MovementArrowGeometry.Groups(new[]{first,passing}).Count==2,"remote middle crossings do not merge when neither origin range is entered");
   b.Motor.Stop();a.Motor.Stop();visual.Refresh();Check(visual.MovingCount==0&&Points(visual).Length==0,"stop removes fixed arrows immediately");a.transform.position=new Vector3(-7,0);Route(a,new Vector2(-6.8f,0));a.Motor.Tick(1);visual.Refresh();Check(!a.Motor.IsMoving&&visual.MovingCount==0&&Points(visual).Length==0,"arrival removes completed fixed arrow");
   File.WriteAllText("fixed-arrow-verification.txt",string.Join("\n",checks));SessionState.SetBool("FixedArrowVerify",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);
  }catch(Exception e){File.WriteAllText("fixed-arrow-verification.txt",e+"\n"+string.Join("\n",checks));SessionState.SetBool("FixedArrowVerify",false);EditorApplication.update-=Poll;Debug.LogException(e);EditorApplication.Exit(1);}}
 }
}
